use strict; use warnings;
use DBI;

my $dbh = DBI->connect("dbi:SQLite:dbname=/app/oewn.sqlite", "", "",
    { RaiseError => 1, ReadOnly => 1 });

my $ws = {};
my $st = $dbh->prepare("SELECT wordid, synsetid, COUNT(*) FROM senses GROUP BY wordid, synsetid");
$st->execute;
while (my @r = $st->fetchrow_array) { $ws->{"$r[0]|$r[1]"} = $r[2]; }

my $syn = {};
$st = $dbh->prepare("SELECT synsetid, domainid, posid FROM synsets");
$st->execute;
while (my @r = $st->fetchrow_array) { $syn->{$r[0]} = [$r[1], $r[2]]; }

my $word = {};
$st = $dbh->prepare("SELECT wordid, word FROM words");
$st->execute;
while (my @r = $st->fetchrow_array) { $word->{$r[0]} = $r[1]; }

my %agg;
for my $k (keys %$ws) {
    my ($wid, $sid) = split /\|/, $k;
    my $c = $ws->{$k};
    my $a = $agg{$wid} ||= { synsets => 0, senses => 0, doms => {}, pos => {}, topsid => undef, topc => undef };
    if (exists $syn->{$sid}) {
        $a->{synsets}++; $a->{senses} += $c;
        $a->{doms}{ $syn->{$sid}[0] } = 1;
        $a->{pos}{ $syn->{$sid}[1] } = 1;
    }
    if (!defined $a->{topsid} || $c > $a->{topc} || ($c == $a->{topc} && $sid < $a->{topsid})) {
        $a->{topsid} = $sid; $a->{topc} = $c;
    }
}

my @rows;
for my $wid (keys %agg) {
    my $a = $agg{$wid};
    next unless $a->{synsets} >= 2 && scalar(keys %{$a->{doms}}) >= 2 && $a->{senses} >= 2;
    push @rows, [$wid, $word->{$wid}, $a->{synsets}, $a->{senses},
                 scalar(keys %{$a->{doms}}), scalar(keys %{$a->{pos}}),
                 $a->{topsid}, $a->{topc}];
}
@rows = sort { $b->[3] <=> $a->[3] || $b->[2] <=> $a->[2] || $b->[4] <=> $a->[4] || $a->[0] <=> $b->[0] } @rows;
@rows = @rows[0 .. 499] if @rows > 500;

open my $fh, "<", "/tmp/sol_out.tsv" or die $!;
my $ok = 1;
my $i = 0;
while (my $line = <$fh>) {
    chomp $line;
    my @g = split /\t/, $line;
    my @e = @{$rows[$i]};
    for my $j (0..7) {
        if ($g[$j] != $e[$j]) { $ok = 0; last; }
    }
    if (!$ok) { print "MISMATCH row $i:\n got      " . join("\t", @g) . "\n expected " . join("\t", @e) . "\n"; last; }
    $i++;
}
close $fh;
print ($ok ? "MATCH" : "MISMATCH"), " | rows compared: $i of ", scalar(@rows), "\n";

